examples.bad:
def fetch():
    try:
        return read()
    except:
        pass

examples.good:
def fetch():
    try:
        return read()
    except Exception as e:
        log(e)
        raise

examples.bad:
def append(item, items=[]):
    items.append(item)
    return items

examples.good:
def append(item, items=None):
    if items is None:
        items = []
    items.append(item)
    return items

examples.bad:
def process(value):
    assert value > 0
    return value

examples.good:
def process(value):
    if value <= 0:
        raise ValueError("value must be positive")
    return value
